__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEGAL_VERSION",{enumerable:!0,get:function(){return l}}),Object.defineProperty(e,"DERNEK_ADI",{enumerable:!0,get:function(){return n}}),Object.defineProperty(e,"DERNEK_ADRES",{enumerable:!0,get:function(){return k}}),Object.defineProperty(e,"CONTACT_EMAIL",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"legalDocs",{enumerable:!0,get:function(){return s}});const l='1.0',n='\xc7orum \u0130li Karg\u0131 \u0130l\xe7esi Karacao\u011flan K\xf6y\xfc Yard\u0131mla\u015fma ve G\xfczelle\u015ftirme Derne\u011fi',k='Hasanpa\u015fa Mah. Tevhid Cad. Atlas Sok. No:11, Sultanbeyli / \u0130stanbul',t="iletisim@susa.app",s={'topluluk-kurallari':{title:'Topluluk Kurallar\u0131',sections:[{p:'SUSA, k\xf6y\xfcm\xfcz\xfcn insanlar\u0131n\u0131 birbirine ba\u011flayan ortak evimizdir. Burada herkesin kendini rahat, g\xfcvende ve sayg\u0131 g\xf6rm\xfc\u015f hissetmesini istiyoruz. Bu kurallar hepimiz i\xe7indir.'},{h:'1. Sayg\u0131 ve nezaket',p:'B\xfcy\xfc\u011fe sayg\u0131, k\xfc\xe7\xfc\u011fe sevgi. Hakaret, k\xfcf\xfcr, alay, a\u015fa\u011f\u0131lama, dedikodu ve ki\u015fileri hedef alan payla\u015f\u0131mlar yasakt\u0131r. Anla\u015famad\u0131\u011f\u0131n\u0131z konularda tart\u0131\u015fmay\u0131 uzatmak yerine \xf6zelden konu\u015fun ya da konuyu b\u0131rak\u0131n.'},{h:'2. Siyaset yok',p:'SUSA siyasi tart\u0131\u015fma yeri de\u011fildir. Parti, aday, se\xe7im ve siyasi kutupla\u015fmaya yol a\xe7acak payla\u015f\u0131m ve yorumlar kald\u0131r\u0131l\u0131r. \u0130nan\xe7, mezhep, k\xf6ken \xfczerinden ayr\u0131\u015ft\u0131r\u0131c\u0131 s\xf6ylemlere izin verilmez.'},{h:'3. \xd6zel hayata sayg\u0131',p:'Ba\u015fkas\u0131n\u0131n foto\u011fraf\u0131n\u0131, \xf6zellikle kad\u0131nlar\u0131m\u0131z\u0131n ve \xe7ocuklar\u0131m\u0131z\u0131n foto\u011fraflar\u0131n\u0131, izni olmadan payla\u015fmay\u0131n. Telefon numaras\u0131, adres, sa\u011fl\u0131k bilgisi gibi \xf6zel bilgileri payla\u015fmay\u0131n. Halkalardaki (Pembe Halka, Mavi Halka, Gen\xe7ler) payla\u015f\u0131mlar\u0131n ekran g\xf6r\xfcnt\xfcs\xfcn\xfc al\u0131p d\u0131\u015far\u0131ya yaymak g\xfcveni bozar ve hesab\u0131n kapat\u0131lma sebebidir.'},{h:'4. Halkalar',p:'Pembe Halka yaln\u0131zca kad\u0131n \xfcyelere, Mavi Halka yaln\u0131zca erkek \xfcyelere, gen\xe7ler halkas\u0131 belirlenen ya\u015f aral\u0131\u011f\u0131ndaki \xfcyelere a\xe7\u0131kt\u0131r. Bu alanlara yanl\u0131\u015f bilgiyle girmeye \xe7al\u0131\u015fmak kal\u0131c\u0131 uzakla\u015ft\u0131rma sebebidir.'},{h:'5. Uygunsuz i\xe7erik',p:'M\xfcstehcen, \u015fiddet i\xe7eren, korkutucu, nefret s\xf6ylemi bar\u0131nd\u0131ran, yasa d\u0131\u015f\u0131 i\xe7erikler kesinlikle yasakt\u0131r. \xc7ocuklar\u0131n istismar\u0131na ili\u015fkin her t\xfcrl\xfc i\xe7erik derhal kald\u0131r\u0131l\u0131r ve yasal mercilere bildirilir.'},{h:'6. Ticaret ve istenmeyen mesajlar',p:'Reklam, zincir mesaj, para isteme, doland\u0131r\u0131c\u0131l\u0131k ve tekrarlayan payla\u015f\u0131mlar yasakt\u0131r. Sat\u0131\u015f ve al\u0131\u015fveri\u015f duyurular\u0131 yaln\u0131zca K\xf6y\xfcm\xfcz \u203a Hem\u015fehri Pazar\u0131 b\xf6l\xfcm\xfcnde yap\u0131l\u0131r.'},{h:'7. Do\u011fruluk',p:'Vefat, hastal\u0131k, d\xfc\u011f\xfcn gibi haberleri teyit etmeden payla\u015fmay\u0131n. Yanl\u0131\u015f bilgi ailelerimizi \xfczebilir.'},{h:'\u015eikayet ve engelleme',p:'Kurallara ayk\u0131r\u0131 bir i\xe7erik g\xf6rd\xfc\u011f\xfcn\xfczde payla\u015f\u0131m\u0131n sa\u011f \xfcst\xfcndeki "\u2026" men\xfcs\xfcnden "\u015eikayet et" se\xe7ene\u011fini kullan\u0131n. \u015eikayetler gizlidir ve en ge\xe7 24 saat i\xe7inde incelenir. Rahats\u0131z oldu\u011funuz bir ki\u015fiyi "Engelle" ile engelleyebilirsiniz; birbirinizin payla\u015f\u0131mlar\u0131n\u0131 g\xf6rmezsiniz. Birden fazla \xfcyenin \u015fikayet etti\u011fi i\xe7erik inceleme bitene kadar otomatik olarak gizlenir.'},{h:'Yapt\u0131r\u0131mlar',p:'Kurala ayk\u0131r\u0131 i\xe7erik kald\u0131r\u0131l\u0131r. Tekrar\u0131nda s\u0131ras\u0131yla uyar\u0131, ge\xe7ici ask\u0131ya alma ve kal\u0131c\u0131 uzakla\u015ft\u0131rma uygulan\u0131r. A\u011f\u0131r ihlallerde (\xe7ocuk g\xfcvenli\u011fi, tehdit, m\xfcstehcenlik) hesap do\u011frudan kapat\u0131l\u0131r.'},{h:'Pembe Halka y\xf6netimi',p:'Pembe Halka\u2019daki (kad\u0131nlar) \u015fikayetleri yaln\u0131zca kad\u0131n moderat\xf6rlerimiz inceler. Erkek y\xf6neticiler dahil hi\xe7bir erkek \xfcye bu halkan\u0131n i\xe7eri\u011fini g\xf6remez; bu kural ki\u015filerin insaf\u0131na b\u0131rak\u0131lmam\u0131\u015ft\u0131r, uygulaman\u0131n kendisi taraf\u0131ndan kesin olarak uygulan\u0131r.'}]},gizlilik:{title:'Gizlilik Politikas\u0131',sections:[{p:'Bu politika, \xc7orum \u0130li Karg\u0131 \u0130l\xe7esi Karacao\u011flan K\xf6y\xfc Yard\u0131mla\u015fma ve G\xfczelle\u015ftirme Derne\u011fi ("Dernek") taraf\u0131ndan sunulan SUSA uygulamas\u0131nda ki\u015fisel verilerinizin nas\u0131l i\u015flendi\u011fini a\xe7\u0131klar.'},{h:'Toplad\u0131\u011f\u0131m\u0131z bilgiler',p:'Hesap: e-posta adresiniz ve \u015fifreniz (\u015fifreniz kimsenin okuyamayaca\u011f\u0131 bi\xe7imde saklan\u0131r). Profil: ad soyad, aile/s\xfclale ad\u0131, cinsiyet, do\u011fum y\u0131l\u0131, ya\u015fad\u0131\u011f\u0131n\u0131z \u015fehir, iste\u011fe ba\u011fl\u0131 tan\u0131t\u0131m yaz\u0131s\u0131 ve profil foto\u011fraf\u0131, k\xf6y\xfcm\xfczle ba\u011f\u0131n\u0131z\u0131 a\xe7\u0131klayan bilgi. \u0130\xe7erik: payla\u015f\u0131mlar\u0131n\u0131z, foto\u011fraf ve videolar\u0131n\u0131z, yorumlar\u0131n\u0131z, be\u011fenileriniz, ar\u015five ekledi\u011finiz foto\u011fraflar, etkinlik kat\u0131l\u0131m bildirimleriniz, cemiyet kay\u0131t talepleriniz. Teknik: bildirim g\xf6nderebilmek i\xe7in cihaz bildirim kimli\u011fi.'},{h:'Toplamad\u0131klar\u0131m\u0131z',p:'Konumunuzu takip etmeyiz. Y\xfckledi\u011finiz foto\u011fraflar\u0131n i\xe7inde sakl\u0131 konum bilgisi y\xfckleme s\u0131ras\u0131nda silinir. Rehberinize eri\u015fmeyiz. Reklam g\xf6stermeyiz; verilerinizi reklam veya pazarlama amac\u0131yla kimseyle payla\u015fmay\u0131z ve satmay\u0131z. Sizi ba\u015fka uygulamalarda ve sitelerde takip etmeyiz.'},{h:'Neden kullan\u0131yoruz',p:'\xdcyeli\u011finizin k\xf6y\xfcm\xfczle ba\u011f\u0131n\u0131n do\u011frulanmas\u0131; halkalara (Pembe Halka: kad\u0131nlar, Mavi Halka: erkekler, Gen\xe7ler) eri\u015fiminizin belirlenmesi (cinsiyet ve do\u011fum y\u0131l\u0131 bu y\xfczden istenir); payla\u015f\u0131mlar\u0131n g\xf6sterilmesi; dernek etkinlik ve duyurular\u0131n\u0131n iletilmesi; topluluk g\xfcvenli\u011finin sa\u011flanmas\u0131 ve \u015fikayetlerin incelenmesi.'},{h:'Kim g\xf6rebilir',p:'Profilinizi ve "T\xfcm K\xf6y" payla\u015f\u0131mlar\u0131n\u0131z\u0131 yaln\u0131zca onayl\u0131 SUSA \xfcyeleri g\xf6r\xfcr; uygulama arama motorlar\u0131na ve \xfcye olmayanlara kapal\u0131d\u0131r. Halka payla\u015f\u0131mlar\u0131n\u0131 yaln\u0131zca o halkan\u0131n \xfcyeleri g\xf6r\xfcr. Cemiyet kayd\u0131ndaki ileti\u015fim telefonunu yaln\u0131zca dernek y\xf6netimi g\xf6r\xfcr.'},{h:'Nerede saklan\u0131yor',p:'Veriler, hizmet sa\u011flay\u0131c\u0131m\u0131z Supabase Inc. arac\u0131l\u0131\u011f\u0131yla Avrupa Birli\u011fi (Frankfurt, Almanya) veri merkezlerinde \u015fifreli ba\u011flant\u0131 ile saklan\u0131r. Yurt d\u0131\u015f\u0131na aktar\u0131m KVKK m.9 kapsam\u0131nda standart s\xf6zle\u015fme ile yap\u0131l\u0131r. Bildirimler Apple ve Google bildirim servisleri \xfczerinden iletilir.'},{h:'Saklama s\xfcresi',p:'Verileriniz \xfcyeli\u011finiz s\xfcrd\xfck\xe7e saklan\u0131r. Hesab\u0131n\u0131z\u0131 sildi\u011finizde profiliniz, payla\u015f\u0131mlar\u0131n\u0131z, yorumlar\u0131n\u0131z, be\u011fenileriniz, foto\u011fraf ve videolar\u0131n\u0131z kal\u0131c\u0131 olarak silinir. K\xf6y\xfcm\xfcz\xfcn ortak haf\u0131zas\u0131n\u0131n par\xe7as\u0131 olan ve y\xf6netim onay\u0131yla Hat\u0131ra Ar\u015fivi\'ne al\u0131nm\u0131\u015f foto\u011fraflar, y\xfckleyen bilgisi kald\u0131r\u0131larak korunabilir; bunlar\u0131n da silinmesini isterseniz bize yazman\u0131z yeterlidir. Yasal y\xfck\xfcml\xfcl\xfckler gere\u011fi tutulmas\u0131 gereken kay\u0131tlar mevzuattaki s\xfcre kadar saklan\u0131r.'},{h:'Hesap silme',p:'Hesab\u0131n\u0131z\u0131 istedi\u011finiz an uygulamada Profil sekmesinin en alt\u0131ndaki "Hesab\u0131m\u0131 sil" se\xe7ene\u011fiyle silebilirsiniz. Uygulamaya eri\u015fiminiz yoksa susa.app/hesap-silme adresinden talepte bulunabilirsiniz.'},{h:'Haklar\u0131n\u0131z',p:'KVKK m.11 kapsam\u0131ndaki haklar\u0131n\u0131z i\xe7in KVKK Ayd\u0131nlatma Metni\'ne bak\u0131n\u0131z.'},{h:'\xc7ocuklar',p:'SUSA\'ya 15 ya\u015f\u0131ndan k\xfc\xe7\xfckler \xfcye olamaz.'},{h:'\u0130leti\u015fim',p:`\xc7orum \u0130li Karg\u0131 \u0130l\xe7esi Karacao\u011flan K\xf6y\xfc Yard\u0131mla\u015fma ve G\xfczelle\u015ftirme Derne\u011fi \u2014 ${k} \u2014 ${t}`}]},kvkk:{title:'KVKK Ayd\u0131nlatma Metni',sections:[{h:'Veri sorumlusu',p:`6698 say\u0131l\u0131 Ki\u015fisel Verilerin Korunmas\u0131 Kanunu ("KVKK") uyar\u0131nca veri sorumlusu \xc7orum \u0130li Karg\u0131 \u0130l\xe7esi Karacao\u011flan K\xf6y\xfc Yard\u0131mla\u015fma ve G\xfczelle\u015ftirme Derne\u011fi'dir. Adres: ${k}. E-posta: ${t}`},{h:'\u0130\u015flenen veriler',p:'Kimlik (ad, soyad, aile ad\u0131, do\u011fum y\u0131l\u0131, cinsiyet), ileti\u015fim (e-posta), g\xf6rsel ve i\u015fitsel kay\u0131tlar (payla\u015ft\u0131\u011f\u0131n\u0131z foto\u011fraf/video), dernek \xfcyeli\u011fi/hem\u015fehrilik ba\u011f\u0131, kullan\u0131c\u0131 i\xe7erikleri ve i\u015flem g\xfcvenli\u011fi verileri.'},{h:'\xd6zel nitelikli veriler',p:'Dernek \xfcyeli\u011fi bilgisi ve payla\u015fabilece\u011finiz foto\u011fraflardaki k\u0131l\u0131k-k\u0131yafet g\xf6r\xfcnt\xfcleri KVKK m.6 kapsam\u0131nda \xf6zel nitelikli ki\u015fisel veri say\u0131labilir. Bu veriler yaln\u0131zca a\xe7\u0131k r\u0131zan\u0131za dayanarak ve Kurul\'un belirledi\u011fi yeterli \xf6nlemler al\u0131narak i\u015flenir.'},{h:'\u0130\u015fleme ama\xe7lar\u0131 ve hukuki sebepler',p:'\xdcyelik s\xf6zle\u015fmesinin kurulmas\u0131 ve ifas\u0131 (m.5/2-c), Derne\u011fin me\u015fru menfaati olan topluluk g\xfcvenli\u011finin sa\u011flanmas\u0131 (m.5/2-f), hukuki y\xfck\xfcml\xfcl\xfcklerin yerine getirilmesi (m.5/2-\xe7) ve \xf6zel nitelikli veriler ile yurt d\u0131\u015f\u0131na aktar\u0131m bak\u0131m\u0131ndan a\xe7\u0131k r\u0131zan\u0131z (m.6, m.9).'},{h:'Aktar\u0131m',p:'Verileriniz, bar\u0131nd\u0131rma hizmeti i\xe7in Supabase Inc.\'e (AB veri merkezi), bildirim iletimi i\xe7in Apple Inc. ve Google LLC\'ye, KVKK m.9\'a uygun olarak aktar\u0131labilir. Yetkili kamu kurumlar\u0131n\u0131n yasal talepleri halinde ilgili mercilere aktar\u0131labilir. Ba\u015fka hi\xe7bir \xfc\xe7\xfcnc\xfc ki\u015fiye aktar\u0131lmaz.'},{h:'Toplama y\xf6ntemi',p:'Verileriniz SUSA mobil ve web uygulamas\u0131 \xfczerinden elektronik ortamda, sizin taraf\u0131n\u0131zdan girilerek toplan\u0131r.'},{h:'Haklar\u0131n\u0131z (m.11)',p:"Verilerinizin i\u015flenip i\u015flenmedi\u011fini \xf6\u011frenme, bilgi talep etme, amac\u0131na uygun kullan\u0131l\u0131p kullan\u0131lmad\u0131\u011f\u0131n\u0131 \xf6\u011frenme, aktar\u0131ld\u0131\u011f\u0131 \xfc\xe7\xfcnc\xfc ki\u015fileri bilme, eksik/yanl\u0131\u015f i\u015flenmi\u015fse d\xfczeltilmesini, silinmesini veya yok edilmesini isteme, otomatik analiz sonucu aleyhinize bir sonuca itiraz etme ve zarara u\u011framan\u0131z halinde tazminat talep etme haklar\u0131na sahipsiniz. Ba\u015fvurular\u0131n\u0131z\u0131 iletisim@susa.app adresine iletebilirsiniz; en ge\xe7 30 g\xfcn i\xe7inde \xfccretsiz olarak sonu\xe7land\u0131r\u0131l\u0131r."}]},'kullanim-kosullari':{title:'Kullan\u0131m Ko\u015fullar\u0131',sections:[{p:'SUSA\'y\u0131 kullanarak bu ko\u015fullar\u0131, Topluluk Kurallar\u0131\'n\u0131 ve Gizlilik Politikas\u0131\'n\u0131 kabul etmi\u015f olursunuz.'},{h:'\xdcyelik',p:'SUSA, Karacao\u011flan K\xf6y\xfc (Karg\u0131, \xc7orum) ile ba\u011f\u0131 bulunan ki\u015filer ve aileleri i\xe7in kapal\u0131 bir topluluktur. \xdcyelik dernek y\xf6netiminin onay\u0131na ba\u011fl\u0131d\u0131r. 15 ya\u015f\u0131ndan k\xfc\xe7\xfckler \xfcye olamaz. Profilinizde do\u011fru bilgi vermeniz zorunludur; \xf6zellikle cinsiyet ve do\u011fum y\u0131l\u0131 halkalara eri\u015fimi belirledi\u011fi i\xe7in onaydan sonra yaln\u0131zca y\xf6netim taraf\u0131ndan de\u011fi\u015ftirilebilir.'},{h:'\u0130\xe7erik sorumlulu\u011fu',p:'Payla\u015ft\u0131\u011f\u0131n\u0131z i\xe7erikten siz sorumlusunuz. Payla\u015ft\u0131\u011f\u0131n\u0131z i\xe7eri\u011fin size ait oldu\u011funu veya payla\u015fma izniniz bulundu\u011funu kabul edersiniz. \u0130\xe7eriklerinizin SUSA i\xe7inde \xfcyelere g\xf6sterilmesi i\xe7in Derne\u011fe m\xfcnhas\u0131r olmayan, \xfccretsiz bir kullan\u0131m izni vermi\u015f olursunuz; bu izin i\xe7eri\u011fi sildi\u011finizde sona erer.'},{h:'Kabul edilemez i\xe7erik',p:'Topluluk Kurallar\u0131\'na ayk\u0131r\u0131, hukuka ayk\u0131r\u0131, m\xfcstehcen, nefret s\xf6ylemi i\xe7eren veya ba\u015fkalar\u0131n\u0131n haklar\u0131n\u0131 ihlal eden i\xe7eriklere s\u0131f\u0131r tolerans uygulan\u0131r. Bu t\xfcr i\xe7erikler kald\u0131r\u0131l\u0131r ve payla\u015fan hesaplar ask\u0131ya al\u0131n\u0131r veya kapat\u0131l\u0131r.'},{h:'Moderasyon',p:'Dernek, kurallara ayk\u0131r\u0131 i\xe7erikleri kald\u0131rma, hesaplar\u0131 ask\u0131ya alma veya kapatma hakk\u0131n\u0131 sakl\u0131 tutar. \u015eikayetler en ge\xe7 24 saat i\xe7inde incelenir.'},{h:'Hizmetin s\xfcreklili\u011fi',p:'SUSA derne\u011fin ortak hizmetidir ve y\xf6netim de\u011fi\u015fikliklerinden ba\u011f\u0131ms\u0131z olarak s\xfcrd\xfcr\xfcl\xfcr. Hizmet "oldu\u011fu gibi" sunulur; bak\u0131m ve g\xfcncellemeler nedeniyle ge\xe7ici kesintiler olabilir.'},{h:'\u0130leti\u015fim',p:t}]},'cocuk-guvenligi':{title:'\xc7ocuk G\xfcvenli\u011fi Standartlar\u0131m\u0131z',sections:[{p:'SUSA, \xe7ocuklar\u0131n cinsel istismar\u0131 ve s\xf6m\xfcr\xfcs\xfcne (CSAE) ve \xe7ocuk cinsel istismar\u0131 i\xe7eriklerine (CSAM) kar\u015f\u0131 s\u0131f\u0131r tolerans politikas\u0131 uygular.'},{h:'Ya\u015f s\u0131n\u0131r\u0131',p:'15 ya\u015f\u0131ndan k\xfc\xe7\xfckler SUSA\'ya \xfcye olamaz. \xdcyelik ba\u015fvurular\u0131 dernek y\xf6netimince tek tek incelenir.'},{h:'Yasak i\xe7erik',p:'\xc7ocuklar\u0131 cinselle\u015ftiren, istismar eden veya tehlikeye atan her t\xfcrl\xfc i\xe7erik, mesaj ve davran\u0131\u015f kesinlikle yasakt\u0131r.'},{h:'Uygulama i\xe7i bildirim',p:'Her payla\u015f\u0131m, yorum ve profilde bulunan "\u015eikayet et > \xc7ocuk g\xfcvenli\u011fi" se\xe7ene\u011fiyle uygulamadan \xe7\u0131kmadan bildirimde bulunabilirsiniz. Bu kategorideki \u015fikayetlerde i\xe7erik derhal gizlenir ve \xf6ncelikli olarak incelenir.'},{h:'Yapt\u0131r\u0131m ve bildirim',p:'\u0130hlal tespit edildi\u011finde i\xe7erik kald\u0131r\u0131l\u0131r, hesap kal\u0131c\u0131 olarak kapat\u0131l\u0131r ve olay ilgili yasal mercilere (Emniyet Genel M\xfcd\xfcrl\xfc\u011f\xfc Siber Su\xe7larla M\xfccadele Daire Ba\u015fkanl\u0131\u011f\u0131, ihbarweb.org.tr) bildirilir.'},{h:'\xc7ocuklar\u0131n foto\u011fraflar\u0131',p:'\xc7ocuklar\u0131n foto\u011fraflar\u0131 yaln\u0131zca velilerinin izniyle ve \xe7ocu\u011fun mahremiyetine sayg\u0131 g\xf6sterilerek payla\u015f\u0131labilir.'},{h:'\u0130leti\u015fim noktas\u0131',p:`\xc7ocuk g\xfcvenli\u011fiyle ilgili t\xfcm konular i\xe7in: ${t}`}]}}},825,[]);
